#include <iostream>
#include <deque>

template <typename T>
class Stack {
public:
    void push(const T& val) {
        stackDeque.push_front(val);
    }

    void pop(); // declared inside, defined outside

    const T& top() const {
        return stackDeque.front();
    }

    bool isEmpty() const {
        return stackDeque.empty();
    }

    std::size_t size() const {
        return stackDeque.size();
    }

private:
    std::deque<T> stackDeque;
};

// Out-of-line member function definition
template <typename T>
inline void Stack<T>::pop() {
    stackDeque.pop_front();
}

int main() {
    Stack<double> doubleStack;
    const std::size_t doubleStackSize = 5;
    double doubleValue = 1.1;

    std::cout << "Pushing elements onto doubleStack\n";
    for (std::size_t i = 0; i < doubleStackSize; ++i) {
        doubleStack.push(doubleValue);
        std::cout << doubleValue << ' ';
        doubleValue += 1.1;
    }

    std::cout << "\n\nPopping elements from doubleStack\n";
    while (!doubleStack.isEmpty()) {
        std::cout << doubleStack.top() << ' ';
        doubleStack.pop();
    }
    std::cout << "\nStack is empty, cannot pop.\n";

    return 0;
}

#include <iostream>
#include <deque>
#include <string>

template <typename T>
class Stack {
public:
    void push(const T& val) { dequeData.push_front(val); }
    void pop() { dequeData.pop_front(); }
    const T& top() const { return dequeData.front(); }
    bool isEmpty() const { return dequeData.empty(); }
private:
    std::deque<T> dequeData;
};

template <typename T>
void testStack(
    Stack<T>& theStack,
    const T& value,
    const T& increment,
    std::size_t size,
    const std::string& stackName
) {
    std::cout << "\nPushing elements onto " << stackName << '\n';
    T pushValue = value;

    for (std::size_t i = 0; i < size; ++i) {
        theStack.push(pushValue);
        std::cout << pushValue << ' ';
        pushValue += increment;
    }

    std::cout << "\n\nPopping elements from " << stackName << '\n';
    while (!theStack.isEmpty()) {
        std::cout << theStack.top() << ' ';
        theStack.pop();
    }
    std::cout << "\nStack is empty. Cannot pop.\n";
}

int main() {
    Stack<double> doubleStack;
    const std::size_t doubleStackSize = 5;
    testStack(doubleStack, 1.1, 1.1, doubleStackSize, "doubleStack");

    Stack<int> intStack;
    const std::size_t intStackSize = 10;
    testStack(intStack, 1, 1, intStackSize, "intStack");

    return 0;
}
